import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Try modifying the student data below
        String name   = "Rahul";
        double marks  = 87.5;
        int rounded   = (int) marks;
        char grade    = (marks >= 75) ? 'B' : 'C';
        boolean pass  = marks >= 40;

        System.out.println("Student : " + name);
        System.out.printf("Marks   : %.1f (Rounded: %d)%n", marks, rounded);
        System.out.println("Grade   : " + grade);
        System.out.println("Result  : " + (pass ? "PASS" : "FAIL"));
    }
}
